# p66: module-level builtins and keyword arguments (P0-26).
#
# The first block calls every builtin with the keyword names CPython's own __text_signature__
# advertises; that list is generated by .artifacts/tmp/gen_builtin_kw_table.py rather than invented
# here. 32 builtins are entirely positional-only and all answer with "name() takes no keyword
# arguments". SharpPy used to drop the keyword and then complain about the argument the keyword was
# meant to supply, so abs(x=-5) said "abs() takes exactly one argument (0 given)": the call being
# refused was not the call being reported.
#
# The rest pins the builtins that do take keywords (round/pow/print/sorted/sum/min/max/enumerate and
# zip(strict=)), the text used for an unknown one - sorted() reports "sort()", because it shares
# list.sort()'s keyword parser - and the fact that the order differs per function: min(zzz=1) reports
# the missing argument, enumerate(zzz=1) reports the invalid keyword. All of it is measured.

def s(label, fn):
    try:
        print(label, repr(fn()))
    except Exception as exc:
        print(label, "EXC", type(exc).__name__ + ":", str(exc)[:70])

s('abs.x', lambda: abs(**{'x': 1}))
s('all.iterable', lambda: all(**{'iterable': [1, 2]}))
s('any.iterable', lambda: any(**{'iterable': [1, 2]}))
s('ascii.obj', lambda: ascii(**{'obj': 5}))
s('bin.number', lambda: bin(**{'number': 2.5}))
s('callable.obj', lambda: callable(**{'obj': 5}))
s('chr.i', lambda: chr(**{'i': 65}))
s('delattr.obj', lambda: delattr(**{'obj': 5}))
s('delattr.name', lambda: delattr(**{'name': 'm'}))
s('divmod.x', lambda: divmod(**{'x': 1}))
s('divmod.y', lambda: divmod(**{'y': 1}))
s('format.value', lambda: format(**{'value': 1}))
s('format.format_spec', lambda: format(**{'format_spec': ''}))
s('hasattr.obj', lambda: hasattr(**{'obj': 5}))
s('hasattr.name', lambda: hasattr(**{'name': 'm'}))
s('hash.obj', lambda: hash(**{'obj': 5}))
s('hex.number', lambda: hex(**{'number': 2.5}))
s('id.obj', lambda: id(**{'obj': 5}))
s('isinstance.obj', lambda: isinstance(**{'obj': 5}))
s('isinstance.class_or_tuple', lambda: isinstance(**{'class_or_tuple': int}))
s('issubclass.cls', lambda: issubclass(**{'cls': int}))
s('issubclass.class_or_tuple', lambda: issubclass(**{'class_or_tuple': int}))
s('len.obj', lambda: len(**{'obj': 5}))
s('oct.number', lambda: oct(**{'number': 2.5}))
s('ord.c', lambda: ord(**{'c': 'a'}))
s('repr.obj', lambda: repr(**{'obj': 5}))
s('setattr.obj', lambda: setattr(**{'obj': 5}))
s('setattr.name', lambda: setattr(**{'name': 'm'}))
s('setattr.value', lambda: setattr(**{'value': 1}))
s('sorted.iterable', lambda: sorted(**{'iterable': [1, 2]}))
s('sum.iterable', lambda: sum(**{'iterable': [1, 2]}))

print("--- keyword-accepting builtins and the unknown-keyword family ---")
s("round_named", lambda: round(number=2.567, ndigits=2))
s("round_ndigits_only", lambda: round(2.567, ndigits=1))
s("round_unknown", lambda: round(2.5, zzz=1))
s("round_zero", lambda: round())
s("round_three_positional", lambda: round(2.5, 1, 2))
s("pow_named", lambda: pow(base=2, exp=10, mod=1000))
s("pow_mod_keyword", lambda: pow(2, 3, mod=5))
s("pow_unknown", lambda: pow(2, 3, zzz=1))
s("pow_zero", lambda: pow())
s("pow_one", lambda: pow(2))
s("pow_four", lambda: pow(2, 3, 5, 6))
s("print_sep_end", lambda: print("a", "b", sep="|", end="~"))
s("print_unknown", lambda: print(zzz=1))
s("sorted_key_reverse", lambda: sorted([1, 20, 3], key=str, reverse=True))
s("sorted_unknown", lambda: sorted([1], zzz=1))
s("sorted_two_positional", lambda: sorted([2, 1], [3]))
s("sum_start_kw", lambda: sum([1, 2], start=10))
s("sum_three_positional", lambda: sum([1], 2, 3))
s("sum_unknown", lambda: sum([1], zzz=1))
s("min_key_default", lambda: (min(["a", "bb"], key=len), min([], default=0)))
s("min_unknown", lambda: min([2, 1], zzz=1))
s("min_unknown_no_positional", lambda: min(zzz=1))
s("max_unknown", lambda: max([2, 1], zzz=1))

print("--- iterator and container factories ---")
s("enum_iterable_kw", lambda: list(enumerate(iterable=[7])))
s("enum_start_kw", lambda: list(enumerate([7], start=1)))
s("enum_unknown", lambda: list(enumerate(zzz=1)))
s("enum_zero", lambda: list(enumerate()))
s("enum_three_positional", lambda: list(enumerate([1], 1, 2)))
s("zip_strict", lambda: list(zip([1], [2], strict=True)))
s("zip_strict_bad_value", lambda: list(zip([1], [2], strict="x")))
s("map_kw", lambda: list(map(function=None, iterable=[1])))
s("filter_kw", lambda: list(filter(function=None, iterable=[1])))
s("range_stop_kw", lambda: list(range(stop=3)))
s("range_named", lambda: list(range(start=0, stop=4, step=2)))
s("slice_named", lambda: (slice(start=1, stop=3).start, slice(start=1, stop=3).step))
s("reversed_kw", lambda: list(reversed(sequence=[1, 2])))
s("reversed_seq_kw", lambda: list(reversed(seq=[1])))
s("reversed_two_positional", lambda: list(reversed([1], 2)))
s("reversed_zero", lambda: list(reversed()))
s("dict_kwargs_are_items", lambda: sorted(dict(a=1)))
s("set_iterable_kw", lambda: sorted(set(iterable=[2, 1])))
s("plain_positionals_still_fine",
  lambda: (abs(-5), len([1, 2]), divmod(7, 2), getattr(type(1), "__name__"), repr(1)))
